// Auto-generated transparent brand assets (no background rects).
// Used by puppeteer-renderer.ts to inject real logos into placeholder tokens.

/** Compass-rose icon — transparent background, white outer ring, 400×400 viewBox */
export const BRAND_ICON_DATA_URI =
  'data:image/svg+xml;base64,';

/** Full wordmark logo — transparent background, 3536×800 viewBox */
export const BRAND_LOGO_DATA_URI =
  'data:image/svg+xml;base64,';

/**
 * Replace placeholder tokens in HTML with real brand asset data URIs.
 * Claude uses these tokens instead of trying to reproduce complex SVG paths.
 *
 *  - \`{{MALLOULIAUTO_LOGO}}\`  → full wordmark (text + icon)
 *  - \`{{MALLOULIAUTO_ICON}}\`  → compass-rose icon only
 */
export function injectBrandAssets(html: string): string {
  return html
    .replace(/\{\{MALLOULIAUTO_LOGO\}\}/g, BRAND_LOGO_DATA_URI)
    .replace(/\{\{MALLOULIAUTO_ICON\}\}/g, BRAND_ICON_DATA_URI);
}
